const script = `
$ProgressPreference='SilentlyContinue'
$h=@{'User-Agent'='dsh-check';'Accept'='application/vnd.github+json'}
$repos = @(
 'Ebony-Vinyl/dsh-our-free-model',
 'corrinehu/dsh-workbuddy-connect',
 'FishBottle7/opencode2dsh',
 'keman-ai/dsh-opencode-zen',
 'x5427876/dsh-opencode-free',
 'artorias-zj/dsh-opencode-free-model',
 'Yee-h/dsh-zen-proxy',
 'ai-yukin/dsh-0-tools',
 'yu-wenchao/dsh-free-models-hub',
 '0xrushmoon/dsh-freeroute',
 'JuwanXu/dsh-free-router',
 'hyqibot/DeepSeek-Harness-Token-Free',
 'XiangSu-ce/dsh-plugin-freecodego',
 'marcosmmjr2023/dsh-h-v1',
 'viztor/dsh-opencode-patch',
 '1624318455/dsh-plugin-adapter'
)
foreach ($rp in $repos) {
  try {
    $i = Invoke-RestMethod -Uri "https://api.github.com/repos/$rp" -Headers $h -TimeoutSec 30
    "$($i.stargazers_count)|$($i.forks_count)|$($i.open_issues_count)|$($i.pushed_at)|$($i.created_at)|$($i.license.spdx_id)|$($i.full_name)|$($i.description)"
  } catch { "ERR|$rp|$($_.Exception.Message)" }
  Start-Sleep -Milliseconds 250
}
`;
const r = await tools.pwsh({ command: script, description: "Fetch stats for alternative plugins", timeoutMs: 180000 });
console.log(r.kind === "foreground" ? (r.stdout.text + r.stderr.text).slice(0, 8000) : JSON.stringify(r).slice(0,500));
